import { Helmet } from "react-helmet";
import * as React from "react"
import Header from '../components/Header'

import Helmet1 from '../components/Helmet'
import Transition from '../components/Transition'
import { Link } from "gatsby"
import dotsw from '../../static/Anindya Biswas white dots.png'
import dotsb from '../../static/Anindya Biswas black dots.png'
import redbg from '../../static/redbg.png'
import red1 from '../../static/red1.png'
import blue1 from '../../static/blue1.png'
import bwbg from '../../static/bg.png'

import $ from 'jquery';
import { faArrowDown, faArrowRight } from '@fortawesome/free-solid-svg-icons'
import { FontAwesomeIcon } from "@fortawesome/react-fontawesome"
import { useState, useEffect } from 'react';



function view(){
  document.getElementById("hi").scrollIntoView({behavior:'smooth'});
}

export default function Home() {
  const [showTransition, setShowTransition] = useState(false);
   const [isClicked, setIsClicked] = useState(false);

   const handleClick = () => {
    setIsClicked((prev) => !prev); // Toggle the clicked state
  };

  useEffect(() => {
    // Check if navigation is forward (not back)
    const navigationType = window.performance.getEntriesByType('navigation')[0]?.type;
    if (navigationType === 'navigate' || navigationType === 'reload') {
      setShowTransition(true); // Show animation only on forward or reload
      const timer = setTimeout(() => setShowTransition(false), 1000);
      return () => clearTimeout(timer);
    }
  }, []);


  if(typeof window !== 'undefined'){
  window.addEventListener("scroll",function(){
    var pageBottom = window.scrollY + window.screen.height;
    var tags = $(".appear");
    var elements = document.getElementsByClassName("appear");

    for (var i = 0; i < tags.length; i++) {

      var tag = tags[i];

    if (elements[i].offsetTop < pageBottom) 
      {
        $(tag).addClass("visible");
      } 
      else
      {
        $(tag).removeClass("visible");

      }
    }

  });
  return(
  <>
{showTransition && <Transition />}
<Helmet>
      <title>Anindya Biswas, IIT Roorkee M.Tech AI | UCSTA IT</title>
      <meta name="description" content="Official portfolio of Anindya Biswas, M.Tech AI IIT Roorkee (IITR), B.Tech IT University of Calcutta (UCSTA) showcasing projects, skills, and achievements in AI, ML, LLM, RAG and software development." />
        <meta name="keywords" content="Anindya Biswas, IIT Roorkee, IITR, MFSDSAI, Mehta Family School of DS and AI, UCSTA, University of Calcutta, Tech Campus, AKCSIT, Amlan Chakrabarti, Durga Toshinwal, Soumya Sen, Wazib Ansar, LLM, RAG, Cohere, OpenAI, portfolio, AI projects, software development, developer, Kolkata, West Bengal, Birati, Ajodhyanagar" />
        <meta name="author" content="Anindya Biswas" />
</Helmet> 
<Header>
   <Helmet1></Helmet1>
    <div className={`flex flex-wrap items-center align-middle justify-evenly h-dvh dark:bg-neutral-800  duration-500  ${isClicked ? "bg-red-500 dark:bg-red-500 duration-1000" : "dark:bg-neutral-800 bg-gray-50"}`}>
      
      
      {/* <img src={dotsw} id="bg" alt="Anindya Biswas" className=" absolute object-cover h-full rotate max-sm:h-2/3 opacity-60 hidden visible dark:block"/>
      <img src={dotsb} id="bg" alt="Anindya Biswas" className=" absolute object-cover h-full rotate max-sm:h-2/3 opacity-60  dark:hidden"/> */}

      {/* <img src={redbg} id="bg" alt="Anindya Biswas" className=" fixed blur-3xl object-cover h-full max-sm:h-2/3 opacity-60 "/> */}
      {/* <img src={red1} id="bg" alt="Anindya Biswas" className=" fixed left-0 h-20 top-0  blur-3xl object-cover max-sm:h-2/3 opacity-60 "/>
      <img src={red1} id="bg" alt="Anindya Biswas" className=" fixed h-40   blur-3xl object-cover max-sm:h-2/3 opacity-60 "/> */}

      <img src={bwbg} id="bg" alt="Anindya Biswas" className=" fixed  bg-cover w-full h-full opacity-70 "/>

      <h1 className={`text-6xl max-sm:text-2xl py-4  text-neutral-200 w-full text-center fade-up z-0 duration-500 ${isClicked ? "bg-red-500 dark:bg-red-500 duration-1000 text-red-200" : ""}`}>
        Welcome to&nbsp;
        <button className="rounded-full text-white duration-500 hover:text-red-600 hover:bg-transparent hover:px-1 "  onClick={handleClick}>Anindya's</button> Home!</h1>
        
        {/* <div className=" bg-gradient-to-l from-red-500 to-red-600 drop-shadow-xl bg-opacity-50 backdrop-blur-3xl text-white font-bold px-7 py-5 rounded-full absolute bottom-12 lg:right-12 hover:bg-red-500 duration-500 z-1" onClick={view}><FontAwesomeIcon icon={faArrowDown}/></div> */}

    </div>


    <div className="flex flex-wrap items-center align-middle justify-evenly bg-gray-50 dark:bg-neutral-900 min-h-screen max-h-fit noise ">
    
      <div className=" p-12  rounded-3xl appear border  dark:text-neutral-200 text-white text-opacity-100 backdrop-blur-xl drop-shadow-2xl bg-opacity-30 bg-neutral-50 dark:bg-neutral-800 dark:bg-opacity-50 dark:border-neutral-800" id="slide2">
        <h1 className=" text-6xl mb-8" id="hi">Hi there! 😁</h1>
        <p className="ms-1 text-lg opacity-70"> It's Anindya Biswas and this is my online home.</p>
        <p className="ms-1 text-lg opacity-70"> I'm currently pursuing my Master's in AI at IITR while exploring the world through fun, creative projects.</p>
        <p className="mb-12 ms-1 text-lg opacity-70">Curious to know more? Head over to About, and don't forget to check out my Works!</p>
        <div className="flex flex-wrap items-center align-middle">

        <Link to="/works" className=" text-2xl border border-red-500 rounded-full py-4 px-7 m-2 text-red-100 drop-shadow-2xl bg-gradient-to-l from-red-500 to-red-600 hover:border-red-50 hover:drop-shadow-lg hover:ease-in-out duration-500">Works <FontAwesomeIcon icon={faArrowRight} size="xs" className=" ms-2"/></Link>
        {/* <Link to="/about" className=" text-2xl border border-red-50 rounded-full py-4 px-7 m-2 drop-shadow-2xl backdrop-blur-3xl backdrop-brightness-150 hover:border-red-400 hover:drop-shadw-lg hover:ease-in-out duration-300 dark:text-red-100">About <FontAwesomeIcon icon={faArrowRight} size="xs" className=" ms-2"/></Link> */}
        <Link to="/about" className=" text-2xl bg-opacity-100 border-red-50 rounded-full py-4 px-7 m-2 drop-shadow-2xl bg-gradient-to-r  text-red-500  from-neutral-300 to-neutral-100 shadow-slate-200  border  hover:border-red-500 hover:drop-shadow-lg hover:ease-in-out duration-500">About <FontAwesomeIcon icon={faArrowRight} size="xs" className=" ms-2"/></Link>
        </div>
      </div>
    </div>

    <div className="flex flex-wrap items-center align-middle justify-evenly bg-gray-50 dark:bg-neutral-900 min-h-screen max-h-fit noise ">
    
        <div className="p-2 w-1/">
          <div className="text-7xl text-opacity-70 text-neutral-100 appear mb-2">Some of the things...<br></br></div>
          
          <div className=" text-5xl text-opacity-40 text-neutral-100 appear ms-2">I've done over the years.</div>
        </div>

        <div className="flex flex-wrap align-middle items-center justify-center p-2 lg:w-1/3">
          <div className="bg-neutral-100/70 hover:bg-neutral-100/90 backdrop-blur-3xl shadow-2xl hover:shadow-lg duration-500 text-neutral-700  rounded-2xl px-8 py-5 max-md: m-1 text-xl appear">LLM</div>
          <div className="bg-neutral-100/70 hover:bg-neutral-100/90 backdrop-blur-3xl shadow-2xl hover:shadow-lg duration-500 text-neutral-700  rounded-2xl px-8 py-5 m-1 text-xl appear">VLM</div>
          <div className="bg-neutral-100/70 hover:bg-neutral-100/90 backdrop-blur-3xl shadow-2xl hover:shadow-lg duration-500 text-neutral-700  rounded-2xl px-8 py-5 m-1 text-xl appear">YOLO</div>
          <div className="bg-neutral-100/70 hover:bg-neutral-100/90 backdrop-blur-3xl shadow-2xl hover:shadow-lg duration-500 text-neutral-700  rounded-2xl px-8 py-5 m-1 text-xl appear">Traffic</div>
          <div className="bg-neutral-100/70 hover:bg-neutral-100/90 backdrop-blur-3xl shadow-2xl hover:shadow-lg duration-500 text-neutral-700  rounded-2xl px-8 py-5 m-1 text-xl appear">NLP</div>
          <div className="bg-neutral-100/70 hover:bg-neutral-100/90 backdrop-blur-3xl shadow-2xl hover:shadow-lg duration-500 text-neutral-700  rounded-2xl px-8 py-5 m-1 text-xl appear">RAG</div>
          <div className="bg-neutral-100/70 hover:bg-neutral-100/90 backdrop-blur-3xl shadow-2xl hover:shadow-lg duration-500 text-neutral-700  rounded-2xl px-8 py-5 m-1 text-xl appear">Vector DB</div>
          <div className="bg-neutral-100/70 hover:bg-neutral-100/90 backdrop-blur-3xl shadow-2xl hover:shadow-lg duration-500 text-neutral-700  rounded-2xl px-8 py-5 m-1 text-xl appear">LangChain</div>
          <div className="bg-neutral-100/70 hover:bg-neutral-100/90 backdrop-blur-3xl shadow-2xl hover:shadow-lg duration-500 text-neutral-700  rounded-2xl px-8 py-5 m-1 text-xl appear">FER</div>
          <div className="bg-neutral-100/70 hover:bg-neutral-100/90 backdrop-blur-3xl shadow-2xl hover:shadow-lg duration-500 text-neutral-700  rounded-2xl px-8 py-5 m-1 text-xl appear">React</div>
          <div className="bg-neutral-100/70 hover:bg-neutral-100/90 backdrop-blur-3xl shadow-2xl hover:shadow-lg duration-500 text-neutral-700  rounded-2xl px-8 py-5 m-1 text-xl appear">Flask</div>
          <div className="bg-neutral-100/70 hover:bg-neutral-100/90 backdrop-blur-3xl shadow-2xl hover:shadow-lg duration-500 text-neutral-700  rounded-2xl px-8 py-5 m-1 text-xl appear">OpenCV</div>
          
          <div className="break bg-red-600/90 backdrop-blur-3xl shadow-2xl text-neutral-200 rounded-2xl p-5 m-1 text-lg">More <FontAwesomeIcon icon={faArrowRight} size="xs" className=" ms-2"/></div>
        </div>

    </div>

    </Header>
    </>
  )

}
}

